from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    go: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for s in banned:
        node = 0
        for ch in s:
            c = char_to_idx[ch]
            nxt = go[node][c]
            if nxt == -1:
                nxt = len(go)
                go[node][c] = nxt
                go.append([-1] * k)
                bad.append(False)
            node = nxt
        bad[node] = True

    num_states = len(go)
    fail = [0] * num_states
    queue: deque[int] = deque()

    for c in range(k):
        nxt = go[0][c]
        if nxt != -1:
            fail[nxt] = 0
            queue.append(nxt)
        else:
            go[0][c] = 0

    while queue:
        u = queue.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = go[u][c]
            if v != -1:
                fail[v] = go[fail[u]][c]
                queue.append(v)
            else:
                go[u][c] = go[fail[u]][c]

    state_id = [-1] * num_states
    valid_states: list[int] = []
    for u in range(num_states):
        if not bad[u]:
            state_id[u] = len(valid_states)
            valid_states.append(u)

    m = len(valid_states)
    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(valid_states):
        for c in range(k):
            v = go[u][c]
            j = state_id[v]
            if j != -1:
                mat[i][j] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for p in range(m):
                aip = ai[p]
                if aip:
                    bp = b[p]
                    for j in range(m):
                        ri[j] += aip * bp[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    def vec_mat_mul(v: list[int], b: list[list[int]]) -> list[int]:
        res = [0] * m
        for i in range(m):
            vi = v[i]
            if vi:
                bi = b[i]
                for j in range(m):
                    res[j] += vi * bi[j]
        return [x % MOD for x in res]

    vec = [0] * m
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            vec = vec_mat_mul(vec, mat)
        exp >>= 1
        if exp > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
